package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("അല്ലാഹുമ്മ ബിക അസ്ബാഹ്ന", "അല്ലാഹുവേ, അങ്ങയുടെ വഴിയേ ഞങ്ങൾ പ്രഭാതത്തിലും അങ്ങയുടെ വഴിയേ ഞങ്ങൾ വൈകുന്നേരത്തിലും പ്രവേശിക്കുന്നു; അങ്ങയുടെ വഴിയേ ഞങ്ങൾ ജീവിക്കുന്നു, അങ്ങയുടെ വഴിയേ ഞങ്ങൾ മരിക്കുന്നു, അങ്ങേയ്ക്കാണ് ഉയിർത്തെഴുന്നേൽപ്പ്.", "രാവിലെ.", "ഇന്ന് രാവിലെയും വൈകുന്നേരവും പറയണമെന്ന് പ്രവാചകൻ സൽഹഅലിഹ് വസ്ൽമൻ കൂട്ടാളികളെ പഠിപ്പിച്ചു."),
        "dua_allahumma_bika_amsayna" to DuaText("അല്ലാഹുമ്മ ബിക അമ്ശൈന", "അല്ലാഹുവേ, അങ്ങയുടെ വഴിയേ ഞങ്ങൾ വൈകുന്നേരങ്ങളിൽ പ്രവേശിക്കുന്നു, അങ്ങയുടെ വഴിയേ ഞങ്ങൾ പ്രഭാതത്തിൽ പ്രവേശിക്കുന്നു; അങ്ങയുടെ വഴിയേ ഞങ്ങൾ ജീവിക്കുന്നു, അങ്ങയുടെ വഴിയേ ഞങ്ങൾ മരിക്കുന്നു, അങ്ങയുടെ വഴിയേയാണ് മടക്കം.", "വൈകുന്നേരങ്ങളിൽ.", "ഇന്ന് രാവിലെയും വൈകുന്നേരവും പറയണമെന്ന് പ്രവാചകൻ സൽഹഅലിഹ് വസ്ൽമൻ കൂട്ടാളികളെ പഠിപ്പിച്ചു."),
        "dua_afiyah_morning" to DuaText("അഫിയയോട് ചോദിക്കുന്നു", "അല്ലാഹുവേ, ഇഹലോകത്തും പരലോകത്തും മാപ്പുതന്നും ക്ഷേമവും ഞാൻ നിന്നോടു യാചിക്കുന്നു.", "നബി (സ) രാവിലെയോ വൈകുന്നേരമോ ഈ ദുആ വിട്ടുപോയിട്ടില്ല.", "ക്ഷേമത്തേക്കാൾ മികച്ചതായി മറ്റാർക്കും ഒന്നും നൽകിയിട്ടില്ല."),
        "dua_afini_fi_badani" to DuaText("ശരീരത്തിന്റെയും കേൾവിശക്തിയുടെയും കാഴ്ചശക്തിയുടെയും ആരോഗ്യം", "അല്ലാഹുവേ, എൻറെ ശരീരത്തിന് നന്മ ചെയ്യേണമേ. അല്ലാഹുവേ, എൻറെ കേൾവിക്ക് നന്മ ചെയ്യേണമേ. അല്ലാഹുവേ, എൻറെ കാഴ്ചയ്ക്ക് നന്മ ചെയ്യണമേ. നിന്നല്ലാതെ ദൈവമില്ല.", "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ വീതം.", "ആരോഗ്യത്തിനും ഇന്ദ്രിയങ്ങളുടെ സംരക്ഷണത്തിനുമുള്ള ഒരു ദുആ."),
        "dua_ya_hayyu_aslih" to DuaText("എൻ്റെ എല്ലാ കാര്യങ്ങളും ശരിയാക്കുക", "ഓ നിത്യജീവനായ, ഓ പരിപാലകനേ, അങ്ങയുടെ കാരുണ്യത്താൽ ഞാൻ സഹായം തേടുന്നുഃ എൻറെ എല്ലാ കാര്യങ്ങളും ശരിയാക്കുക, എന്നെ ഒരു കണ്ണ് ചിമ്മുകപോലും എനിക്ക് വിട്ടുകൊടുക്കരുത്.", "രാവിലെയും വൈകുന്നേരവും ഇത് പറയണമെന്ന് നബി (സ) ഫാത്തിമയോട് ഉപദേശിച്ചു.", "എല്ലാ കാര്യങ്ങളിലും അല്ലാഹുവിൻ്റെ സഹായം തേടുക."),
        "dua_subhanallah_adada_khalqihi" to DuaText("ജുവേരിയയിലെ തസ്ബിയ (റ)", "അല്ലാഹുവിന് മഹത്വമുണ്ട്, എല്ലാ സ്തുതികളും അവനുതന്നെയാണ്-അവൻറെ സൃഷ്ടി എത്രത്തോളം, അവനെ ഇഷ്ടപ്പെടുന്നുവോ അത്രയും, അവന്റെ സിംഹാസനത്തിൻറെ ഭാരത്തിനും വചനങ്ങളുടെ മഷിക്കും തുല്യമാണ്.", "രാവിലെ മൂന്ന് തവണ-മണിക്കൂറുകളേക്കാൾ ഭാരം കൂടിയത്.", "ഈ നാല് വാക്യങ്ങൾ മൂന്ന് തവണ പറയുക എന്നത് പുലർച്ചെ മുതൽ അർദ്ധരാത്രി വരെ ധിക്കറിനെക്കാൾ വലുതാണ്."),
        "dua_salawat" to DuaText("ദുറൂദ്-ഇ-ഇബ്രാഹിം", "അല്ലാഹുവേ, നീ മുഹമ്മദിനും (അ) ഇബ്രാഹിമിൻ്റെയും കുടുംബത്തിനും വേണ്ടി പ്രാർത്ഥന നടത്തിയപ്പോൾ മുഹമ്മദ് സല്ലല്ലാഹു അലൈഹി വസല്ലമിനും മുഹമ്മദിൻ്റെയും കുടുംബത്തിനും വേണ്ടി പ്രാർത്ഥന അയയ്ക്കുക. നീ സ്തുത്യർഹനും മഹത്വമുള്ളവനുമാണ്. അല്ലാഹുവേ, നീ മുഹമ്മദിനെയും മുഹമ്മദിൻ്റെയും കുടുംബത്തെയും അനുഗ്രഹിക്കട്ടെ. നീ ഇബ്രാഹിമിനെയും (അ) ഇബ്രാഹിമിൻ്റെയും കുടുംബത്തെയും അനുഗ്രഹിച്ചതുപോലെ. നീ സ്തുത്യർഹനും മഹത്വമുള്ളവനുമാണ്.", "പ്രാർത്ഥനയിലും എല്ലായ്പ്പോഴും പ്രവാചകൻറെ മേൽ സലാവത്ത്.", "ആരെങ്കിലും ഒരു തവണ സലാവത്ത് അയച്ചാൽ അല്ലാഹു അദ്ദേഹത്തിന് പത്ത് കരുണാനിധിയാണ് അയയ്ക്കുന്നത് (408)."),
        "dua_wudu_after" to DuaText("വുഡു കഴിഞ്ഞാൽ", "അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ലെന്നും, അല്ലാഹുവല്ലാതെ, പങ്കാളിയില്ലാതെ, മുഹമ്മദ് നബി (സ) അവൻറെ ദാസനും ദൂതനും ആണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. അല്ലാഹുവേ, എന്നെ പശ്ചാത്തപിക്കുന്നവരുടെയും സ്വയം ശുദ്ധീകരിക്കുന്നവരുടെയും കൂട്ടത്തിലാകണമേ.", "വുഡു പൂർത്തിയാക്കിയ ശേഷം.", "പറുദീസയുടെ എട്ട് കവാടങ്ങൾ അവന് ഇഷ്ടമുള്ളവരിലൂടെ പ്രവേശിക്കാൻ തുറന്നിരിക്കുന്നു."),
        "dua_wudu_before" to DuaText("വുഡുക്ക് മുമ്പ്", "അല്ലാഹുവിൻറെ നാമത്തിൽ.", "വുഡു ആരംഭിക്കുമ്പോൾ.", "അല്ലാഹുവിൻറെ പേര് അതിൽ പരാമർശിക്കാത്ത ഒരാൾക്ക് (പൂർണ്ണ) വുഡു ഇല്ല."),
        "dua_istiftah" to DuaText("പ്രാർത്ഥനയുടെ തുടക്കം (സന)", "അല്ലാഹുവേ, നിനക്ക് മഹത്വവും സ്തുതിയും ഉണ്ടാകട്ടെ. നിൻറെ നാമം അനുഗ്രഹിക്കപ്പെട്ടതാണ്. നിൻറെ പ്രതാപം അത്യുന്നതമാണ്. നിന്നല്ലാതെ ദൈവമില്ല.", "പ്രാർത്ഥനയുടെ തുടക്കത്തിൽ, ഉദ്ഘാടന തക്ബീറിന് തൊട്ടുപിന്നാലെ.", "നമസ്കാരത്തിൻ്റെ ഉദ്ഘാടന ദുആ സുന്നത്ത്."),
        "dua_ruku" to DuaText("റുക്കുവിൽ", "മഹത്തായ എൻറെ രക്ഷിതാവിന് സ്തുതി.", "കുറഞ്ഞത് മൂന്ന് തവണയെങ്കിലും റുക്കുവിൽ.", "റുക്കുവിലെ സുന്നഹ് തസ്ബിഹ്."),
        "dua_sujood" to DuaText("സുജൂദിൽ", "അത്യുന്നതനായ എൻറെ രക്ഷിതാവിന് സ്തുതി.", "കുറഞ്ഞത് മൂന്ന് തവണയെങ്കിലും സുജൂദിൽ.", "സാഷ്ടാംഗം ചെയ്യുന്ന സമയത്ത് ദാസൻ തൻറെ നാഥനോട് ഏറ്റവും അടുത്തിരിക്കുന്നു (മുസ്ലിം 482)."),
        "dua_rising_ruku" to DuaText("റുക്കുവിൽ നിന്ന് ഉയർന്നുവരുന്നു", "തന്നെ സ്തുതിക്കുന്നവൻറെ വാക്കുകൾ അല്ലാഹു കേൾക്കുന്നു. ഞങ്ങളുടെ രക്ഷിതാവേ, എല്ലാ സ്തുതിയും അങ്ങേയ്ക്കാണ്.", "റുക്കുവിൽ നിന്ന് എഴുന്നേറ്റ് നിവർന്ന് നിൽക്കുമ്പോൾ.", "'റബ്ബാന വ ലകൽ-ഹംദ്'മാലാഖമാരുടെ പാപങ്ങളുമായി പൊരുത്തപ്പെടുന്നവർക്ക്, അവന്റെ മുൻകാല പാപങ്ങൾ ക്ഷമിക്കപ്പെടും."),
        "dua_between_sajdas" to DuaText("രണ്ട് സജ്ജദാസുകൾക്കിടയിൽ", "എൻറെ രക്ഷിതാവേ, എന്നോട് ക്ഷമിക്കണമേ. എൻറെ രക്ഷിതാവേ, എന്നോട് ക്ഷമിക്കണമേ.", "രണ്ട് സാഷ്ടാംഗങ്ങൾക്കിടയിൽ ഇരിക്കുമ്പോൾ.", "സാഷ്ടാംഗ നമസ്കാരങ്ങൾക്കിടയിൽ ഇരിക്കുന്നവരുടെ സുന്നത്ത് ദുആ."),
        "dua_before_salam_four" to DuaText("നാല് കാര്യങ്ങളിൽ നിന്നുള്ള അഭയം (സലാമിന് മുമ്പ്)", "അല്ലാഹുവേ, നരകശിക്ഷയിൽ നിന്നും, ശവകുടീരശിക്ഷയിൽ നിന്നും, ജീവിതത്തിന്റെയും മരണത്തിന്റെയും പരീക്ഷണങ്ങളിൽ നിന്നും, വ്യാജ മിശിഹായുടെ (ദജ്ജൽ) വിചാരണയുടെ തിന്മയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "അവസാന താഷാഹുദിനും സലാവത്തിനും ശേഷം സലാമിന് മുമ്പ്.", "ഈ നാല് കാര്യങ്ങളിൽ നിന്ന് അഭയം തേടാൻ പ്രവാചകൻ കൽപിച്ചു."),
        "dua_qunoot_witr" to DuaText("വിത്തറിൽ കുനൂട്ട്", "അല്ലാഹുവേ, നീ നേർവഴിയിലാക്കിയവരുടെ കൂട്ടത്തിൽ എന്നെ നയിക്കേണമേ. നീ എനിക്ക് നന്മ നൽകിയവരുടെ കൂട്ടത്തിൽ എനിക്ക് നന്മ നൽകണമേ. നീ എന്നെ നീ പരിപാലിക്കുന്നവരുടെ കൂട്ടത്തിൽ എന്നെ ഉൾപ്പെടുത്തണമേ. നീ നൽകിയതിൽ എന്നെ അനുഗ്രഹിക്കണമേ. നീ വിധിച്ചതിൻറെ തിന്മയിൽ നിന്ന് എന്നെ സംരക്ഷിക്കണമേ. നീ വിധിച്ചിരിക്കുന്നു. നിനക്കെതിരെ ഒരു വിധികളും ഇല്ല. നീ സൌഹൃദം പുലർത്തുന്നവൻ ഒരിക്കലും അപമാനിക്കപ്പെടുകയുമില്ല. ഞങ്ങളുടെ രക്ഷിതാവേ, നീ ഭാഗ്യവാൻ. നീ പരിശുദ്ധൻ.", "വിർ പ്രാർത്ഥനയിൽ-പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു വസ്ലം അത് ഹസൻ ഇബ്നു അലി (റ) യെ പഠിപ്പിച്ചു.", "വിത്രിലെ സുന്നത്ത് കുനൂട്ട്. (ഹനഫികളിൽ'അല്ലാഹുമ്മ ഇന്ന നസ്താനുക'യും അറിയപ്പെടുന്നു.)"),
        "dua_qunoot_hanafi" to DuaText("കുനൂത്ത് (അല്ലാഹുമ്മ ഇന്ന നസ്തായിനുക)", "അല്ലാഹുവേ, ഞങ്ങൾ നിൻറെ സഹായവും പാപമോചനവും തേടുന്നു. ഞങ്ങൾ നിന്നിൽ വിശ്വസിക്കുകയും നിന്നിൽ ആശ്രയിക്കുകയും ചെയ്യുന്നു. ഞങ്ങൾ നിന്നെ ഏറ്റവും നല്ല രീതിയിൽ സ്തുതിക്കുകയും ചെയ്യുന്നു. ഞങ്ങൾ നന്ദി പറയുന്നു. നന്ദികെട്ടവരല്ല. നിങ്ങളെ ധിക്കരിക്കുന്നവരെ ഞങ്ങൾ ഉപേക്ഷിക്കുകയും ചെയ്യുന്നു. അല്ലാഹുവേ, നിന്നെ മാത്രമാണ് ഞങ്ങൾ ആരാധിക്കുന്നത്. ഞങ്ങൾ നിന്നോട് പ്രാർത്ഥിക്കുകയും സാഷ്ടാംഗം ചെയ്യുകയും ചെയ്യുന്നു. ഞങ്ങൾ തിടുക്കത്തിൽ നിന്നോട് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു. ഞങ്ങൾ നിൻറെ കാരുണ്യത്തിനായി കാത്തിരിക്കുന്നു. നിൻറെ ശിക്ഷയെ ഭയപ്പെടുകയും ചെയ്യുന്നു. തീർച്ചയായും നിൻറെ ശിക്ഷ സത്യനിഷേധികളിൽ എത്തും.", "വിർ-ഹനഫികളുടെ ആചാരം.", "ഖുർആനിൽ ഉമർ (റ) റിപ്പോർട്ട് ചെയ്തു."),
        "dua_sleep_aslamtu" to DuaText("ഉറങ്ങുന്നതിനുമുമ്പുള്ള അവസാന വാക്കുകൾ", "അല്ലാഹുവേ, ഞാൻ നിന്നെത്തന്നെ കീഴടക്കുന്നു. എൻറെ കാര്യം നിനക്ക് സമർപ്പിക്കുകയും, നിന്നിൽ പ്രതീക്ഷയും ഭയവും ഉള്ളതിനാൽ എൻറെ പുറം നിൻറെ സംരക്ഷണത്തിനായി സമർപ്പിക്കുകയും ചെയ്യുന്നു. നിനക്കല്ലാതെ നിനക്ക് ഒരു അഭയവും ഇല്ല. നിന്നിൽ നിന്ന് രക്ഷയുമില്ല. നീ അവതരിപ്പിച്ച നിൻറെ ഗ്രന്ഥത്തിലും നീ അയച്ച നിൻറെ പ്രവാചകനിലും ഞാൻ വിശ്വസിക്കുന്നു.", "വൂഡുവിന് ശേഷം, വലതുവശത്ത് കിടക്കുക-ഉറങ്ങുന്നതിനുമുമ്പുള്ള അവസാന വാക്കുകൾ.", "ആ രാത്രി അവൻ മരിക്കുകയാണെങ്കിൽ, അവൻ ഫിത്ര (ഇസ്ലാം) പ്രകാരം മരിക്കുന്നു."),
        "dua_waking_night" to DuaText("രാത്രിയിൽ ഉണരുക", "അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല. അവന്നാകുന്നു പങ്കാളിയില്ലാതെ. അവന്നാകുന്നു ആധിപത്യം. അവന്നാകുന്നു സ്തുതിയും. അവനാണ് എല്ലാറ്റിൻ്റെയും മേൽ അധികാരവും. എല്ലാ സ്തുതിയും അല്ലാഹുവിനുമാണ്. അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല. അല്ലാഹു ഏറ്റവും വലിയവനാണ്. അല്ലാഹുവല്ലാതെ ശക്തിയോ ശക്തിയോ ഇല്ല. അല്ലാഹുവേ, എന്നോട് നീ പൊറുത്തുതരേണമേ.", "രാത്രിയിൽ ഉണർന്നപ്പോൾ.", "അദ്ദേഹത്തിൻ്റെ ദുആയ്ക്ക് ഉത്തരം നൽകപ്പെടുകയും അദ്ദേഹം വുഡു ചെയ്യുകയും പ്രാർത്ഥിക്കുകയും ചെയ്താൽ അദ്ദേഹത്തിൻ്റെ പ്രാർത്ഥന സ്വീകരിക്കപ്പെടുകയും ചെയ്യുന്നു."),
        "dua_hamm_ibn_masud" to DuaText("ദുഃഖത്തിനുള്ള ദുആ (ഇബ്നു മസൂദ്)", "അല്ലാഹുവേ, ഞാൻ നിൻറെ ദാസനാണ്, നിൻറെ ദാസൻറെ മകൻ, നിൻറെ ദാസിയുടെ മകൻ, നിൻറെ ദാസിയുടെ മകൻ. എൻറെ മുൻഭാഗം നിൻറെ കയ്യിലാണ്. എൻറെ മേൽ നിൻറെ കൽപ്പന നടപ്പാക്കപ്പെടുന്നു. എന്നെക്കുറിച്ചുള്ള നിൻറെ കൽപ്പന നീതിയുള്ളതാണ്. നീ നിൻറെ പേരിൽ വിളിക്കുകയോ, നിൻറെ പുസ്തകത്തിൽ അവതരിപ്പിക്കുകയോ, നിൻറെ ഏതെങ്കിലും സൃഷ്ടിയെക്കുറിച്ച് പഠിപ്പിക്കുകയോ, അദൃശ്യമായതിനെക്കുറിച്ചുള്ള അറിവ് നിൻറെ പക്കൽ സൂക്ഷിക്കുകയോ ചെയ്ത നിൻറെ എല്ലാ പേരുകളാലും ഞാൻ നിന്നോട് ചോദിക്കുന്നു. ഖുർആനെ നീ എൻറെ ഹൃദയത്തിൻറെ ഉറവയാക്കുകയോ, എൻറെ നെഞ്ചിലെ വെളിച്ചമാക്കുകയോ, എൻറെ ദുഃഖം ഇല്ലാതാക്കുകയോ, എൻറെ ആശങ്കകൾ ഉപേക്ഷിക്കുകയോ ചെയ്യുക.", "ദുഃഖത്തിലും സങ്കടത്തിലും-അല്ലാഹു ദുഃഖത്തെ സന്തോഷത്താൽ മാറ്റിസ്ഥാപിക്കുന്നു.", "അല്ലാഹു അദ്ദേഹത്തിൻറെ ഉത്കണ്ഠയും സങ്കടവും നീക്കം ചെയ്യുകയും അതിൻറെ സ്ഥാനത്ത് അദ്ദേഹത്തിന് സന്തോഷം നൽകുകയും ചെയ്യുന്നു."),
        "dua_difficulty_sahl" to DuaText("എന്തെങ്കിലും ബുദ്ധിമുട്ടായിരിക്കുമ്പോൾ", "അല്ലാഹുവേ, നീ എളുപ്പമാക്കുന്നതല്ലാതെ മറ്റൊന്നും എളുപ്പമല്ല. നീ ആഗ്രഹിക്കുന്നുവെങ്കിൽ പ്രയാസം എളുപ്പമാക്കുകയും ചെയ്യുന്നു.", "എന്തെങ്കിലും ബുദ്ധിമുട്ട് തോന്നുമ്പോൾ.", "പരീക്ഷയിൽ എളുപ്പവും ബുദ്ധിമുട്ടുള്ള ജോലികളും."),
        "dua_musibah" to DuaText("ഒരു ദുരന്തത്തിൽ (ഇസ്തിർജ)", "ഞങ്ങൾ അല്ലാഹുവിൻ്റെതാകുന്നു. അവൻ്റെ അടുത്തേക്കാണ് ഞങ്ങൾ മടങ്ങുന്നത്. അല്ലാഹുവേ, എൻറെ കഷ്ടതയിൽ എനിക്ക് പ്രതിഫലം നൽകുകയും, അതിൽനിന്ന് എനിക്ക് മെച്ചപ്പെട്ട എന്തെങ്കിലും നൽകുകയും ചെയ്യേണമേ.", "ഏതെങ്കിലും നഷ്ടത്തിലോ ദുരന്തത്തിലോ.", "അല്ലാഹു തീർച്ചയായും അതിലും മികച്ച എന്തെങ്കിലും നൽകുന്നു-ഉം സലമ (റ) നബി (സ) ക്ക് നൽകപ്പെട്ടു."),
        "dua_debt" to DuaText("കടത്തിൽ നിന്നുള്ള ആശ്വാസത്തിനായി", "അല്ലാഹുവേ, നീ നിഷിദ്ധമാക്കിയതിന് എതിരെ നീ അനുവദനീയമാക്കിയതുകൊണ്ട് എനിക്ക് മതി. നിൻറെ അനുഗ്രഹത്താൽ നീയല്ലാതെ മറ്റെല്ലാത്തിൽ നിന്നും എന്നെ സ്വതന്ത്രനാക്കുക.", "കടം തിരിച്ചടയ്ക്കുന്നതിന്-അലി (ആർ. എ) പഠിപ്പിച്ചതാണ്.", "കടം ഒരു പർവ്വതം പോലെയാണെങ്കിലും അല്ലാഹു അത് തീർക്കും."),
        "dua_anger" to DuaText("ദേഷ്യപ്പെടുമ്പോൾ", "ശപിക്കപ്പെട്ട ഷൈത്താൻ എന്നവനിൽനിന്ന് ഞാൻ അല്ലാഹുവിൽ അഭയം തേടുന്നു.", "ദേഷ്യപ്പെടുമ്പോൾ.", "നബി (സ) പറഞ്ഞുഃ അദ്ദേഹം ഇങ്ങനെ പറഞ്ഞാൽ അദ്ദേഹത്തിൻറെ കോപം ഇല്ലാതാകും."),
        "dua_waswasa" to DuaText("വിശ്വാസത്തിൽ വാസവാസയ്ക്കെതിരെ", "ഞാൻ അല്ലാഹുവിലും അവൻറെ ദൂതന്മാരിലും വിശ്വസിക്കുന്നു.", "വിശ്വാസത്തെക്കുറിച്ച് സാത്താൻറെ മന്ത്രിപ്പുകൾ വരുമ്പോൾ.", "മന്ത്രി വരുമ്പോൾ ഇത് പറയുകയും അവിടെ നിർത്തുകയും ചെയ്യുക (അല്ലാഹുവിൽ അഭയം തേടുകയും ചെയ്യുക)."),
        "dua_travel_full" to DuaText("സമ്പൂർണ്ണ യാത്രാവിധാനം", "അല്ലാഹുവേ, ഈ യാത്രയിൽ നീ നന്മയ്ക്കും ഭക്തിക്കും വേണ്ടി ഞങ്ങൾ നിന്നോടു പ്രാർത്ഥിക്കുന്നു. നിനക്ക് ഇഷ്ടമുള്ള കർമ്മങ്ങൾക്കും. അല്ലാഹുവേ, ഈ യാത്ര ഞങ്ങൾക്ക് എളുപ്പമാക്കുകയും അതിൻറെ ദൂരം കുറയ്ക്കുകയും ചെയ്യേണമേ. അല്ലാഹുവേ, നീ യാത്രയിലെ കൂട്ടാളിയും കുടുംബത്തിൻറെ രക്ഷാധികാരിയുമാണ്.", "ഒരു യാത്രയ്ക്ക് പുറപ്പെടുമ്പോൾ,'സുഭാനല്ലധി സഖറ'ക്ക് ശേഷം.", "സമ്പൂർണ്ണ സുന്നത്ത് യാത്ര ദുആ."),
        "dua_return_travel" to DuaText("യാത്രയിൽ നിന്ന് മടങ്ങിയെത്തി", "നാം മടങ്ങിവരികയും പശ്ചാത്തപിക്കുകയും നമ്മുടെ കർത്താവിനെ ആരാധിക്കുകയും സ്തുതിക്കുകയും ചെയ്യുന്നു.", "ഒരു യാത്രയിൽ നിന്ന് മടങ്ങിയെത്തിയപ്പോൾ.", "ഒരു യാത്ര കഴിഞ്ഞ് മടങ്ങിയെത്തിയപ്പോഴാണ് നബി (സ) ഇത് പറഞ്ഞത്."),
        "dua_farewell_traveller" to DuaText("ഒരു യാത്രക്കാരനോട് വിടപറയൽ", "നിങ്ങളുടെ മതവും വിശ്വാസവും നിങ്ങളുടെ കർമ്മങ്ങളുടെ ഫലവും ഞാൻ അല്ലാഹുവിന് സമർപ്പിക്കുന്നു.", "ഒരു സഞ്ചാരിയോട് വിടപറയുമ്പോൾ.", "അല്ലാഹുവിന് ഏൽപ്പിക്കപ്പെട്ടവ ഒരിക്കലും നഷ്ടപ്പെടുന്നില്ല."),
        "dua_entering_town" to DuaText("ഒരു സ്ഥലത്ത് നിർത്തുക", "അവൻ സൃഷ്ടിച്ച എല്ലാ തിന്മകളിൽ നിന്നും ഞാൻ അല്ലാഹുവിൻറെ പൂർണ്ണമായ വചനങ്ങളിൽ അഭയം തേടുന്നു.", "ഒരു സ്ഥലത്ത് നിർത്തുമ്പോഴോ ഒരു പുതിയ പട്ടണത്തിൽ എത്തുമ്പോഴോ.", "അവിടെ നിന്ന് പോകുന്നതുവരെ ഒന്നും അവനെ ഉപദ്രവിക്കില്ല."),
        "dua_boarding_ship" to DuaText("ഒരു കപ്പൽ/വാഹനം കയറുക", "അല്ലാഹുവിൻറെ നാമത്തിൽ അതിൻറെ കപ്പലും നങ്കൂരവും ഉണ്ട്. തീർച്ചയായും എൻറെ രക്ഷിതാവ് ഏറെ പൊറുക്കുന്നവനും കരുണാനിധിയുമാകുന്നു.", "ഒരു കപ്പലിലോ വാഹനത്തിലോ കയറുമ്പോൾ-നൂഹ് (അ. സ.) നബിയുടെ വാക്കുകൾ.", "ഖുർആൻ വചനമായ നൂഹിൻറെ (എ. എസ്) പെട്ടകത്തിൻറെ ദുആ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("ഹയുൽ-ഖയ്യൂമിനൊപ്പം ഇസ്തിഗ്ഫർ", "ഞാൻ അല്ലാഹുവോട് പാപമോചനം തേടുന്നു, അവനല്ലാതെ ഒരു ദൈവവുമില്ല, നിത്യനും പരിപാലകനും, ഞാൻ അവനോട് പശ്ചാത്തപിക്കുന്നു.", "പശ്ചാത്താപത്തിന്.", "യുദ്ധക്കളത്തിൽ നിന്ന് ഓടിപ്പോയെങ്കിലും അദ്ദേഹത്തിൻ്റെ പാപങ്ങൾ ക്ഷമിക്കപ്പെടും."),
        "dua_rabbighfir_warham" to DuaText("റബ്ബിഗ്ഫിർ വാർഹാം", "എൻറെ രക്ഷിതാവേ, നീ പൊറുത്തുതരികയും കരുണ കാണിക്കുകയും ചെയ്യേണമേ. നീയാണ് കരുണ കാണിക്കുന്നവരിൽ ഏറ്റവും നല്ലവൻ.", "ഖുർആൻ ദുആ-പാപമോചനത്തിനും കരുണയ്ക്കും.", "സൂറ അൽ മുമിനൂണിന്റെ അവസാനത്തെ വാക്യം."),
        "dua_majlis_kaffarah" to DuaText("കഫ്രത്ത് അൽ മജ്ലിസ്", "അല്ലാഹുവേ, നിനക്ക് മഹത്വവും സ്തുതിയും ഉണ്ടാകട്ടെ. നിന്നല്ലാതെ ദൈവമില്ലെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. ഞാൻ നിന്നോട് പാപമോചനം തേടുകയും നിന്നോട് പശ്ചാത്തപിക്കുകയും ചെയ്യുന്നു.", "ഒരു ഒത്തുചേരലിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ.", "സമ്മേളനത്തിൽ പറഞ്ഞ തെറ്റുകൾക്കെല്ലാം അത് ഒരു പരിഹാരമായി മാറുന്നു."),
        "dua_jami_forgiveness" to DuaText("സമഗ്രമായ ക്ഷമ", "അല്ലാഹുവേ, എൻറെ തെറ്റുകൾ, എൻറെ അജ്ഞത, എൻറെ കാര്യങ്ങളിൽ എൻറെ അമിതമായ ഇടപെടൽ, എന്നെക്കാൾ നന്നായി നീ അറിയുന്നതെല്ലാം എന്നോട് ക്ഷമിക്കണമേ.", "നബി (സ) യുടെ സമഗ്രമായ ഒരു ദുആ.", "നബി (സ) ഈ ദുആ ഉണ്ടാക്കാറുണ്ടായിരുന്നു."),
        "dua_parents_nuh" to DuaText("മാതാപിതാക്കൾക്കായി നൂഹ് (എ. എസ്) ദുആ", "എൻറെ രക്ഷിതാവേ, എൻറെ മാതാപിതാക്കളേ, എൻറെ വീട്ടിൽ വിശ്വാസിയായി പ്രവേശിച്ചവർക്കും, സത്യവിശ്വാസികളായ പുരുഷന്മാർക്കും സ്ത്രീകൾക്കും നീ പൊറുത്തുതരേണമേ.", "ഒരാളുടെ മാതാപിതാക്കൾക്കും വിശ്വാസികൾക്കും വേണ്ടി.", "നൂഹ് (അ. സ.) നബിയുടെ ദൂതം."),
        "dua_shukr_parents" to DuaText("മാതാപിതാക്കൾക്കും നീതിമാന്മാരായ സന്തതികൾക്കും നന്ദി", "എൻറെ രക്ഷിതാവേ, എനിക്കും എൻറെ മാതാപിതാക്കൾക്കും നീ നൽകിയ അനുഗ്രഹത്തിന് നന്ദിയുള്ളവനായിരിക്കുവാനും, നിനക്ക് ഇഷ്ടമുള്ള സൽകർമ്മങ്ങൾ ചെയ്യാനും, എൻറെ സന്തതികളെ നീതിമാന്മാരാക്കുവാനും എന്നെ അനുവദിക്കണമേ. ഞാൻ നിന്നോട് പശ്ചാത്തപിക്കുന്നു. ഞാൻ കീഴ്പെടുന്നവരുടെ കൂട്ടത്തിലാകുന്നു.", "നാൽപ്പത് വയസ്സ് തികയുന്ന ഖുർആൻ ദുആ.", "നന്ദിയും സൽപ്രവൃത്തികളും മക്കളുടെ നീതിയും-എല്ലാം ഒരു ദ്വയത്തിൽ."),
        "dua_intimacy" to DuaText("വൈവാഹിക ബന്ധങ്ങൾക്ക് മുമ്പ്", "അല്ലാഹുവിൻറെ നാമത്തിൽ. അല്ലാഹുവേ, ഷൈതാനെ ഞങ്ങളിൽ നിന്ന് അകറ്റിനിർത്തുക. നീ ഞങ്ങൾക്ക് നൽകുന്നതിൽ നിന്ന് ഷൈതാനെ അകറ്റിനിർത്തുക.", "വൈവാഹിക ബന്ധങ്ങൾക്ക് മുമ്പ്.", "ഒരു കുട്ടിയെ വിധിക്കുകയാണെങ്കിൽ, ശായ്താൻ ഒരിക്കലും അതിനെ ഉപദ്രവിക്കില്ല."),
        "dua_ibrahim_children_protection" to DuaText("വീടുകളുടെയും കുട്ടികളുടെയും സംരക്ഷണം", "എൻറെ കർത്താവേ, ഈ നഗരം സുരക്ഷിതമാക്കുകയും എന്നെയും എൻറെ മക്കളെയും വിഗ്രഹാരാധനയിൽ നിന്ന് അകറ്റിനിർത്തുകയും ചെയ്യേണമേ.", "പ്രവാചകൻ ഇബ്രാഹിം (അ. സ.)-നഗരത്തിന്റെയും മക്കളുടെയും സുരക്ഷയ്ക്കായി.", "തൌഹീദിൽ ഉറച്ചുനിൽക്കുന്നതിനുള്ള ഒരു ദുആ."),
        "dua_drinking_milk" to DuaText("പാൽ കുടിക്കുമ്പോൾ", "അല്ലാഹുവേ, ഞങ്ങൾക്ക് വേണ്ടി അത് അനുഗ്രഹിക്കേണമേ, അതിൽ കൂടുതൽ നൽകൂ.", "പാൽ കുടിക്കുമ്പോൾ.", "ഭക്ഷണവും പാനീയവും എന്ന നിലയിൽ പാൽ മതിയാകും."),
        "dua_iftar_host" to DuaText("മറ്റുള്ളവരുമായി വേഗത്തിൽ ഇടപഴകുമ്പോൾ", "ഉപവാസം ചെയ്യുന്നവർ നിങ്ങളോടൊപ്പം അവരുടെ ഉപവാസം അവസാനിപ്പിക്കട്ടെ, നീതിമാന്മാർ നിങ്ങളുടെ ഭക്ഷണം കഴിക്കട്ടെ, ദൂതന്മാർ നിങ്ങൾക്കായി പ്രാർത്ഥിക്കട്ടെ.", "ആരുടെയെങ്കിലും വീട്ടിൽ വ്രതം അവസാനിപ്പിക്കുമ്പോൾ.", "ആതിഥേയർക്കായി പ്രവാചകൻറെ സലീം."),
    )
}
